def make_spec(choices):
    """Model decisions are explicit, external to prompts and traceable in sidecars."""
    assert set(choices)=={task['id'] for task in TASKS}
    shots={}
    for index,(lens,brief) in BRIEFS.items():
        ident=f'shot-{index:03d}'
        forest=31<=index<=33 or 36==index or 42<=index<=68
        # No device or camp prop list is appended to a macro/empty forest crop.
        lighting=NIGHT if forest and index not in (52,54,59,60,61,63,64,66,68) else ''
        # Four additional forest hero frames use the route demonstrated by control 042.
        # Other tasks keep the faster model; each still requires visual review.
        engine=choices['shot-042'] if index in (44,48,56,66) else 'klein'
        shots[ident]={'prompt':f'{lens}. {brief} {lighting} {PHOTO}'.strip(),
            'description':brief,'lens':lens,'refs':[],'engine':engine}
    for task in TASKS:
        shots[task['id']]={'prompt':task['prompt'],'refs':[],'engine':choices[task['id']]}
    return shots
